        for(const char* id:{"character","brightness","movement","space","palette","velocitytone","presettrim","touch"})if(!snapshot.parameters.getChildWithProperty("id",id).isValid())set(id,0);
        for(int i=0;i<4;++i)for(const char* suffix:{"source","dest","amount"}){auto id=routeId(i,suffix);if(!snapshot.parameters.getChildWithProperty("id",id).isValid())set(id.toRawUTF8(),0);}if(!snapshot.parameters.getChildWithProperty("id","modrate").isValid())set("modrate",1);
        clearFactoryComparison();for(auto child:snapshot.parameters){auto id=child.getProperty("id").toString();auto* parameter=state.getParameter(id);auto range=parameter->getNormalisableRange();set(id.toRawUTF8(),std::clamp(static_cast<float>(child.getProperty("value")),range.start,range.end));}
        multiEnabled.store(snapshot.useZones);program.store(std::clamp(snapshot.program,-1,nova::factoryPresetCount-1));arpEnabled.store(snapshot.arp);arpBpm.store(snapshot.bpm);for(int i=0;i<nova::arpSteps;++i)arpNotes[i].store(snapshot.pattern[i]);{const juce::ScopedLock lock(metadataLock);learnedReviewRevision=snapshot.reviewToken;lastRefinement.reset();comparison={};diagnosticReport="Version restaurada: vuelve a preparar la comparacion.";}say("Restaurada: "+snapshot.name+". Deshacer ajuste recupera el estado anterior.");return true;
