        {const juce::ScopedLock meta(metadataLock);if(!reviewIsCurrentLocked()||reviewChosen.empty()){message="Revisa el audio y elige al menos una nota antes de aprender.";return false;}file=reviewFile;range=reviewInput;analysis=nova::chosenReviewNotes(*review,reviewChosen);}
