    void toggleReference(int mode=0,bool comparisonPair=false,int manualRow=-1,int reviewRow=-1){
        if(referencePlaying()&&previewMode.load()==mode){stopReference();return;}
        if(fitting.load()||loading.load())return;
        auto file=sourceView();auto range=selectedRange();float auditionVelocity=.8f;
        if(manualRow>=0){const juce::ScopedLock lock(metadataLock);if(manualRow>=static_cast<int>(referenceRows.size()))return;file=referenceRows[manualRow].file;range=referenceRows[manualRow].range;}
        if(reviewRow>=0){const juce::ScopedLock lock(metadataLock);if(!reviewIsCurrentLocked()||reviewRow>=static_cast<int>(review->rows.size()))return;file=reviewFile;range=review->rows[reviewRow].note.range;range.start+=reviewInput.start;range.end+=reviewInput.start;auditionVelocity=review->rows[reviewRow].note.velocity;}
        if(!file)return;
        if(mode==3&&range.length()>3&&manualRow<0&&learnedContextNotes().empty()){say("Aprende el contexto primero o selecciona una nota de hasta 3 s para A afinado.");return;}
        if(manualRow<0&&reviewRow<0&&(comparisonPair||mode!=0)){const juce::ScopedLock lock(metadataLock);if(contextFile==file&&std::abs(range.start-contextInput.start)<.00001&&std::abs(range.end-contextInput.end)<.00001&&!contextNotes.empty())range=contextNotes[std::clamp(comparisonZone.load(),0,static_cast<int>(contextNotes.size())-1)].range;else if(range.length()>3&&mode!=0){message="Aprende primero el contexto para comparar una nota representativa.";return;}}
        stopReference();if(previewWorker.joinable())previewWorker.join();auto id=audition.stop();previewMode.store(mode);previewLoading.store(true);
        auto patch=params();std::shared_ptr<nova::SpectralModel> model;std::shared_ptr<nova::ZoneBank> zones;{const juce::ScopedLock lock(metadataLock);model=canonicalModel;zones=canonicalBank;}
        bool arp=reviewRow<0&&arpEnabled.load(),level=matchLevel.load();bool automatic=autoPitch.load()||(reviewRow>=0&&patch.useZones);float bpm=arpBpm.load();std::array<int,nova::arpSteps> pattern{};for(int i=0;i<nova::arpSteps;++i)pattern[i]=arpNotes[i].load();
        previewWorker=std::thread([this,file,range,id,mode,patch,model,zones,arp,level,bpm,pattern,automatic,auditionVelocity]{
            try{juce::AudioFormatManager reader;reader.registerBasicFormats();auto source=readSelectedReference(reader,*file,range,false,60);if(mode!=0)nova::analyse(*source);
                nova::Sound output;if(mode==1||mode==2)output=nova::renderRecreation(*source,patch,model.get(),zones.get(),arp,pattern,bpm,auditionVelocity,automatic?-1:patch.root);
                if(mode==2){auto diagnostic=nova::diagnose(*source,output,automatic&&source->tonal?source->root:patch.root);if(audition.current(id)){const juce::ScopedLock lock(metadataLock);diagnosticReport=nova::diagnosticText(diagnostic);} }
                else {if(mode==3){auto centred=nova::centredTarget(nova::makeTarget(*source,source->root,source->sampleRate,false));output.sampleRate=centred.rate;output.left=std::move(centred.left);output.right=std::move(centred.right);}if(mode==0)output=std::move(*source);if(level)nova::normaliseAudition(output);auto clip=std::make_unique<nova::SelectionPreview::Clip>();clip->sound=std::move(output);clip->start=range.start;clip->generation=id;audition.publish(std::move(clip));}
            }catch(const std::exception& e){if(audition.current(id))say("No se pudo comparar: "+juce::String(e.what()));}
            previewLoading.store(false);
        });
    }
