    void centrePitch(){if(fitting.load()||loading.load())return;rememberPatch();stopReference();for(const char* key:{"fine","tracking","detune","chorus","lfodepth"})set(key,0);set("unison",0);program.store(-1);{const juce::ScopedLock lock(metadataLock);comparison={};diagnosticReport="Tono centrado: vuelve a diagnosticar.";}say("Tono centrado: Tune, movimiento tonal, detune, chorus y LFO de tono a cero. No modifica MIDI pitch bend.");}
