    void undoFit(){clearFactoryComparison();if(!undoReady||fitting.load()||loading.load())return;stopReference();auto current=params();std::shared_ptr<nova::SpectralModel> model;std::shared_ptr<nova::ZoneBank> bank;{const juce::ScopedLock lock(metadataLock);model=canonicalModel;bank=canonicalBank;}int previousProgram=program.load();bool arp=arpEnabled.load();float bpm=arpBpm.load();std::array<int,nova::arpSteps> pattern;for(int i=0;i<nova::arpSteps;++i){pattern[i]=arpNotes[i].load();arpNotes[i].store(undoPattern[i]);}arpBpm.store(undoBpm);undoBpm=bpm;undoPattern=pattern;publishModel(undoModel);publishBank(undoBank);setFromParams(undoParameters);program.store(undoProgram);arpEnabled.store(undoArp);undoParameters=current;undoModel=model;undoBank=bank;undoProgram=previousProgram;undoArp=arp;{const juce::ScopedLock lock(metadataLock);comparison={};diagnosticReport="Ajuste intercambiado: vuelve a diagnosticar.";}say("Ajuste anterior recuperado. Pulsa otra vez para alternar.");}
    int learnedZones()const{const juce::ScopedLock lock(metadataLock);return canonicalBank?canonicalBank->count:0;}
    void captureReference(float velocity){
        if(fitting.load()||loading.load())return;const juce::ScopedLock lock(metadataLock);if(!referenceFile){message="Carga una referencia y marca una nota en MUESTRA.";return;}if(referenceRows.size()>=nova::maxZones){message="El banco admite hasta ocho referencias. Quita una antes de agregar otra.";return;}
        if(selection.length()>3.0001){message="La lista manual necesita una nota de hasta 3 s. Para una frase larga usa Aprender contexto.";return;}referenceRows.push_back({referenceFile,selection,std::clamp(velocity,.05f,1.f)});message="Nota agregada al banco. Marca otra nota o carga otro archivo.";
    }
    juce::StringArray referenceNames()const{const juce::ScopedLock lock(metadataLock);juce::StringArray names;for(size_t i=0;i<referenceRows.size();++i)names.add(juce::String(static_cast<int>(i+1))+". "+referenceRows[i].file->file.getFileName()+" / "+juce::String(referenceRows[i].range.start,2)+" s");return names;}
    juce::StringArray contextNames()const{const juce::ScopedLock lock(metadataLock);juce::StringArray names;if(contextFile==referenceFile&&std::abs(selection.start-contextInput.start)<.00001&&std::abs(selection.end-contextInput.end)<.00001)for(const auto& n:contextNotes)names.add("MIDI "+juce::String(n.note)+" / "+juce::String(n.range.start,2)+" s / variacion "+juce::String(n.centsSpread,1)+" c");return names;}
    void removeReference(int index=-1){if(fitting.load()||loading.load())return;const juce::ScopedLock lock(metadataLock);if(!referenceRows.empty()){if(index<0)index=static_cast<int>(referenceRows.size())-1;if(index<static_cast<int>(referenceRows.size()))referenceRows.erase(referenceRows.begin()+index);}}
    void clearReferences(){if(fitting.load()||loading.load())return;{const juce::ScopedLock lock(metadataLock);referenceRows.clear();contextFile.reset();contextNotes.clear();learnedReviewRevision=~uint64_t{0};}multiEnabled.store(false);publishBank(nullptr);}
    bool startBankFit(){
        const juce::ScopedLock lock(jobLock);if(fitting.load()||loading.load())return false;std::vector<ReferenceRow> rows;{const juce::ScopedLock meta(metadataLock);rows=referenceRows;}if(rows.empty()){say("Agrega al menos una nota al banco.");return false;}
        stopReference();if(worker.joinable())worker.join();cancel.store(false);done.store(false);fitting.store(true);fitProgress.store(0);fitTrials.store(0);analysisStage.store(0);pendingArp={};pendingContext.reset();pendingBank.reset();refinementJob=reviewLearningJob=false;bool clean=cleanPitch.load();int budget=std::max(70,quality.load()/2);
        worker=std::thread([this,rows,clean,budget]{try{
            auto bank=std::make_shared<nova::ZoneBank>();int completed=0;result={};
            for(const auto& row:rows){if(cancel.load())break;analysisStage.store(0);auto sound=readSelectedReference(formats,*row.file,row.range);if(!sound->tonal)throw std::runtime_error("Una referencia no tiene tono estable. Usa notas aisladas para el banco.");
                auto target=nova::makeTarget(*sound,sound->root,budget>=600?44100:22050,false);analysisStage.store(1);auto fit=nova::fitParameters(target,nova::Params{},budget,cancel,[&](int trial,int,double loss){fitTrials.store(completed*budget+trial);fitProgress.store(static_cast<float>(completed*budget+trial)/(rows.size()*budget));fitError.store(static_cast<float>(loss));},2,{},false,clean);
                if(cancel.load())break;if(!fit.valid||!fit.model)throw std::runtime_error("No se pudo reconstruir una de las notas del banco.");
                bool duplicate=false;for(int i=0;i<bank->count;++i)if(bank->zones[i].model.root==fit.model->root&&std::abs(bank->zones[i].velocity-row.velocity)<.03f){bank->zones[i]={*fit.model,row.velocity};duplicate=true;}
                if(!duplicate)bank->zones[bank->count++]={*fit.model,row.velocity};result=fit;++completed;
            }
            if(!cancel.load()&&bank->valid()){pendingBank=bank;result.parameters.useZones=true;result.parameters.engine=1;result.trials=completed*budget;result.valid=true;result.error="Banco por nota/intensidad: modelos sintetizados, sin audio PCM.";}else result.cancelled=true;
        }catch(const std::exception& e){result={};result.error=e.what();}catch(...){result={};result.error="No se pudo crear el banco.";}done.store(true,std::memory_order_release);});return true;
    }
