    static State::ParameterLayout layout(){
        State::ParameterLayout l;juce::StringArray waves{"Sine","Saw","Pulse","Triangle","Soft Organ","Legacy"};
        for(const char* id:{"wavea","waveb"})l.add(std::make_unique<juce::AudioParameterChoice>(juce::ParameterID{id,1},id,waves,juce::String(id)=="wavea"?1:0));
        l.add(std::make_unique<juce::AudioParameterFloat>(juce::ParameterID{"boost",1},"Gain dB",juce::NormalisableRange<float>(-12,12,.1f),0));
        // Keep legacy IDs for project loading; live DSP always uses procedural synthesis.
        l.add(std::make_unique<juce::AudioParameterChoice>(juce::ParameterID{"mode",1},"Legacy mode",juce::StringArray{"Synth","Legacy"},0));
        l.add(std::make_unique<juce::AudioParameterBool>(juce::ParameterID{"loop",1},"Legacy loop",false));
        l.add(std::make_unique<juce::AudioParameterBool>(juce::ParameterID{"unison",1},"Unison x3",true));
        l.add(std::make_unique<juce::AudioParameterChoice>(juce::ParameterID{"synthengine",1},"Synthesis engine",juce::StringArray{"FM / subtractive","48 partial oscillators","Procedural wavetable","Plucked waveguide","Blown resonator"},0));
        for(int i=0;i<nova::partialCount;++i)l.add(std::make_unique<juce::AudioParameterFloat>(juce::ParameterID{partialId(i),1},"Partial "+juce::String(i+1),juce::NormalisableRange<float>(0,2,.001f),1));
        for(const auto& s:controls)l.add(std::make_unique<juce::AudioParameterFloat>(juce::ParameterID{s.id,1},s.label,juce::NormalisableRange<float>(s.minimum,s.maximum,s.step,s.skew),s.initial));
        for(int i=0;i<5;++i)l.add(std::make_unique<juce::AudioParameterBool>(juce::ParameterID{effectIds[i],1},effectNames[i],true));
        for(const char* id:{"character","brightness","movement","space","velocitytone"})l.add(std::make_unique<juce::AudioParameterFloat>(juce::ParameterID{id,1},id,juce::NormalisableRange<float>(0,1,.001f),0));
        l.add(std::make_unique<juce::AudioParameterInt>(juce::ParameterID{"palette",1},"Signature spectrum",0,6,0));
        l.add(std::make_unique<juce::AudioParameterFloat>(juce::ParameterID{"presettrim",1},"Preset calibration dB",juce::NormalisableRange<float>(-12,36,.01f),0));
        l.add(std::make_unique<juce::AudioParameterFloat>(juce::ParameterID{"touch",1},"Expressive touch",juce::NormalisableRange<float>(0,1,.001f),0));
        l.add(std::make_unique<juce::AudioParameterFloat>(juce::ParameterID{"modrate",1},"LFO2 Hz",juce::NormalisableRange<float>(.03f,15,.001f,.4f),1));
        for(int i=0;i<4;++i){l.add(std::make_unique<juce::AudioParameterInt>(juce::ParameterID{routeId(i,"source"),1},"Mod source "+juce::String(i+1),0,6,0));l.add(std::make_unique<juce::AudioParameterInt>(juce::ParameterID{routeId(i,"dest"),1},"Mod target "+juce::String(i+1),0,4,0));l.add(std::make_unique<juce::AudioParameterFloat>(juce::ParameterID{routeId(i,"amount"),1},"Mod amount "+juce::String(i+1),juce::NormalisableRange<float>(-1,1,.001f),0));}
        return l;
    }
